// Emit a single item carrying the full payload (clinics array + account list)
// so downstream pre-fetch + clinic loop can each access what they need.
const input = $input.first().json.body || $input.first().json;
const clinics = input.clinics || [];
const dryRun = input.dry_run || false;
const mode = input.mode || 'single';

if (clinics.length === 0) {
  return [{ json: { error: 'No clinics provided', clinics: [], account_ids: [], dry_run: dryRun, mode } }];
}

return [{ json: {
  dry_run: dryRun,
  mode,
  clinics,
  account_ids: ["act_10201019819851931", "act_708812601077037", "act_293603336988341", "act_3684421665103341", "act_249137098153238", "act_1738224836936889", "act_1093083055897528"]
}}];

// Build new targeting per ad set, skip if upstream emitted a no-match placeholder.
const items = $input.all();
const results = [];

for (const item of items) {
  if (item.json.skip) {
    // Pass through skip marker so loop still completes
    results.push({ json: { skip: true, clinic_id: item.json.clinic_id, clinic_name: item.json.clinic_name, reason: item.json.reason } });
    continue;
  }
  const adsets = item.json.body?.data || item.json.data || [];
  const fbGeoLocations = item.json.fb_geo_locations;
  const dryRun = item.json.dry_run;
  const clinicId = item.json.clinic_id;
  const clinicName = item.json.clinic_name;
  const campaignName = item.json.campaign_name;

  for (const adset of adsets) {
    if (!['ACTIVE', 'PAUSED'].includes(adset.status)) continue;
    const currentTargeting = adset.targeting || {};
    const newTargeting = { ...currentTargeting };
    if (fbGeoLocations.geo_locations) newTargeting.geo_locations = fbGeoLocations.geo_locations;
    if (fbGeoLocations.excluded_geo_locations) newTargeting.excluded_geo_locations = fbGeoLocations.excluded_geo_locations;
    if (newTargeting.geo_locations && !newTargeting.geo_locations.location_types) {
      newTargeting.geo_locations.location_types = ['home', 'recent'];
    }
    results.push({ json: {
      adset_id: adset.id,
      adset_name: adset.name,
      adset_status: adset.status,
      clinic_id: clinicId,
      clinic_name: clinicName,
      campaign_name: campaignName,
      new_targeting: newTargeting,
      dry_run: dryRun
    }});
  }
}

if (results.length === 0) {
  return [{ json: { skip: true, reason: 'no eligible ad sets' } }];
}
return results;

// Aggregate results per clinic from BOTH branches:
// - Ad-set updates (fields: adset_id, body, statusCode) — successes/errors/skips
// - Saved-audience updates (fields: sa_account_id, sa_saved_audience_id, sa_success)
// Skip detection: dry_run flag, skip marker (from Match/Build), or no body data.
const items = $input.all();
const clinicResults = {};
const savedAudienceResults = [];

for (const item of items) {
  const d = item.json;
  const clinicId = d.clinic_id;
  if (!clinicId) continue;

  // Saved-audience branch item
  if (d.sa_account_id) {
    let status = 'error';
    if (d.sa_success) status = 'updated';
    else if (d.dry_run) status = 'skipped';
    else if (d.sa_skipped) status = 'skipped';
    savedAudienceResults.push({
      clinic_id: clinicId,
      account_id: d.sa_account_id,
      saved_audience_id: d.sa_saved_audience_id,
      status,
      ...(d.sa_error ? { error: d.sa_error } : {})
    });
    continue;
  }

  // Ad-set branch item
  if (!clinicResults[clinicId]) {
    clinicResults[clinicId] = {
      clinic_id: clinicId,
      clinic_name: d.clinic_name,
      adsets_updated: 0,
      adsets_errors: 0,
      adsets_skipped: 0,
      details: []
    };
  }

  const isSkip = d.skip === true || d.dry_run === true || (!d.body && !d.statusCode);
  const success = d.body?.success === true || d.statusCode === 200;

  if (success) {
    clinicResults[clinicId].adsets_updated++;
  } else if (isSkip) {
    clinicResults[clinicId].adsets_skipped++;
  } else {
    clinicResults[clinicId].adsets_errors++;
    clinicResults[clinicId].details.push({
      adset_id: d.adset_id,
      error: d.body?.error?.message || `HTTP ${d.statusCode || '?'}`
    });
  }
}

// Per-clinic status
const results = Object.values(clinicResults).map(r => ({
  ...r,
  status: r.adsets_updated > 0 ? 'updated'
        : r.adsets_skipped > 0 && r.adsets_errors === 0 ? 'skipped'
        : 'error'
}));

let updated = 0, skipped = 0, errors = 0;
for (const r of results) {
  if (r.status === 'updated') updated++;
  else if (r.status === 'skipped') skipped++;
  else errors++;
}

let saUpdated = 0, saErrors = 0, saSkipped = 0;
for (const r of savedAudienceResults) {
  if (r.status === 'updated') saUpdated++;
  else if (r.status === 'error') saErrors++;
  else if (r.status === 'skipped') saSkipped++;
}

return [{
  json: {
    success: true,
    results,
    saved_audience_results: savedAudienceResults,
    summary: {
      updated, skipped, errors,
      saved_audiences: { updated: saUpdated, errors: saErrors, skipped: saSkipped }
    }
  }
}];

// Fan out clinics × accounts to one item per (clinic, account) where a saved audience exists
// AND the audience is classified as drive_time in fb_saved_audiences. legacy_geo / unknown
// audiences are skipped (and reported as such) so we don't blow away hand-crafted targeting.
const cfg = $('Parse Input').first().json;
const clinics = cfg.clinics || [];

// Build set of allowed (account_id|audience_id) keys from Supabase response
const rows = ($input.first().json.data || $input.first().json || []);
const allowed = new Set();
for (const r of (Array.isArray(rows) ? rows : [])) {
  if (r.account_id && r.audience_id) allowed.add(`${r.account_id}|${r.audience_id}`);
}

const out = [];
for (const c of clinics) {
  const ids = c.fb_saved_audience_ids || {};
  for (const [accountId, savedAudienceId] of Object.entries(ids)) {
    if (!savedAudienceId) continue;
    const key = `${accountId}|${savedAudienceId}`;
    if (!allowed.has(key)) {
      // emit a skip marker so Format Response can report it
      out.push({ json: {
        clinic_id: c.clinic_id,
        clinic_name: c.clinic_name,
        sa_account_id: accountId,
        sa_saved_audience_id: savedAudienceId,
        sa_skipped: true,
        sa_skip_reason: 'not_drive_time',
        sa_success: false,
        dry_run: cfg.dry_run
      }});
      continue;
    }
    out.push({ json: {
      clinic_id: c.clinic_id,
      clinic_name: c.clinic_name,
      fb_geo_locations: c.fb_geo_locations,
      dry_run: cfg.dry_run,
      sa_account_id: accountId,
      sa_saved_audience_id: savedAudienceId
    }});
  }
}
return out;

// Tag the response with clinic_id + account_id so Format Response can route it
const r = $input.first().json;
const src = $('Fan-out Saved Audiences').item.json;
const ok = r.statusCode >= 200 && r.statusCode < 300 && !r.body?.error;
return [{ json: {
  clinic_id: src.clinic_id,
  clinic_name: src.clinic_name,
  sa_account_id: src.sa_account_id,
  sa_saved_audience_id: src.sa_saved_audience_id,
  sa_success: ok,
  sa_error: ok ? null : (r.body?.error?.message || `HTTP ${r.statusCode}`)
}}];

// Spread to one item per ad account so HTTP iterates per-item
const cfg = $input.first().json;
return cfg.account_ids.map(account_id => ({ json: { account_id, dry_run: cfg.dry_run, mode: cfg.mode, clinics: cfg.clinics } }));

// Aggregate per-account campaign responses into a single cache: { campaigns: {acct: [...]} }
// HTTP pagination produces multiple items per source account; use pairedItem to map
// each page back to its source.
const accounts = $('Spread to 7 Accounts').all();
const respItems = $input.all();

function extractData(item) {
  const j = item.json;
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.data)) return j.data;
  if (Array.isArray(j.body?.data)) return j.body.data;
  return [];
}

function sourceIndex(item) {
  const p = item.pairedItem;
  if (typeof p === 'number') return p;
  if (Array.isArray(p) && p.length) return p[0].item ?? 0;
  if (p && typeof p === 'object') return p.item ?? 0;
  return 0;
}

const cache = { campaigns: {} };
for (const a of accounts) cache.campaigns[a.json.account_id] = [];

for (const item of respItems) {
  const idx = sourceIndex(item);
  const acct = accounts[idx]?.json.account_id;
  if (!acct) continue;
  cache.campaigns[acct].push(...extractData(item));
}

const orig = $('Parse Input').first().json;
return [{ json: {
  dry_run: orig.dry_run,
  mode: orig.mode,
  clinics: orig.clinics,
  account_ids: orig.account_ids,
  cache
}}];

// Spread the clinics array into one item per clinic, ready for Loop Over Clinics.
// Each item carries the dry_run flag and a reference to access the cache via $('Aggregate Cache').
const cfg = $input.first().json;
return cfg.clinics.map(c => ({ json: {
  clinic_id: c.clinic_id,
  clinic_name: c.clinic_name,
  fb_geo_locations: c.fb_geo_locations,
  fb_saved_audience_ids: c.fb_saved_audience_ids || {},
  dry_run: cfg.dry_run,
  mode: cfg.mode,
  account_ids: cfg.account_ids
}}));

// Match this clinic's campaigns from the pre-fetched cache (no HTTP call).
// Filter campaigns whose name contains the clinic name and status is ACTIVE/PAUSED.
// Emit one item per matched campaign for the downstream Get Ad Sets node.
const clinic = $('Loop Over Clinics').item.json;
const cache = $('Aggregate Cache').first().json.cache;
const clinicNameLc = clinic.clinic_name.toLowerCase();

const matches = [];
for (const accountId of clinic.account_ids) {
  const camps = cache.campaigns[accountId] || [];
  for (const c of camps) {
    if (c.name && c.name.toLowerCase().includes(clinicNameLc) && ['ACTIVE','PAUSED'].includes(c.status)) {
      matches.push({ json: {
        ...clinic,
        campaign_id: c.id,
        campaign_name: c.name,
        campaign_status: c.status,
        account_id: accountId
      }});
    }
  }
}

if (matches.length === 0) {
  // emit a placeholder so the loop iteration completes (skip downstream via flag)
  return [{ json: { ...clinic, skip: true, reason: 'no campaigns matched' } }];
}
return matches;
